package cd.kinshasa.smartcity.dashboard.web; import cd.kinshasa.smartcity.dashboard.dto.*; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*; @RestController @RequestMapping("/api/dashboard") public class DashboardController{ @GetMapping("/stats") DashboardStats stats(){return new DashboardStats(10,20,10,5);} @GetMapping("/communes") List<CommuneStats> communes(){return List.of(new CommuneStats("Gombe",3),new CommuneStats("Limete",5),new CommuneStats("Kalamu",2));} @GetMapping("/evolution") List<EvolutionData> evolution(){return java.util.stream.IntStream.range(0,7).mapToObj(i->new EvolutionData(LocalDate.now().minusDays(6-i).toString(), i+2)).toList();}}
